        .success());
    let decision = root.join(".callisto/nested/release-decision.json");
    let out = callisto(root, &["version", "--emit-decision", decision.to_str().unwrap()]);
    assert_eq!(out.status.code(), Some(0), "{}", stderr_of(&out));
    assert!(decision.exists());
}

